<script setup lang="ts">
import PlantSearchInput from "../components/PlantSearchInput.vue"
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePlantsStore} from '../stores/plants'
import type {PlantRecord} from '../types/plant'
import BotanicalCard from '../components/BotanicalCard.vue'
import BotanicalImage from '../components/BotanicalImage.vue'
import DiscoveryPaths from '../components/DiscoveryPaths.vue'
import UiIcon from '../components/UiIcon.vue'
import {discoveryParams,discoveryName,discoverySnippet,uniquePlants,type DiscoveryResult} from '../ui/discovery'
const route=useRoute(),router=useRouter(),plants=usePlantsStore(),query=ref(''),layout=ref('grid'),selected=ref<PlantRecord|null>(null),preview=ref<HTMLDialogElement|null>(null),featured=ref<PlantRecord[]>([])
const leafShape=ref(''),flowerColour=ref(''),growthForm=ref(''),matchResult=ref<DiscoveryResult|null>(null),matchLoading=ref(false),matchError=ref('')
const appliedQuery=computed(()=>typeof route.query.q==='string'?route.query.q:'')
const hasTraits=computed(()=>Boolean(discoveryParams(route.query).size)),visiblePlants=computed(()=>uniquePlants(!appliedQuery.value&&!hasTraits.value?featured.value:[],plants.items))
const matches=computed(()=>{const q=appliedQuery.value.trim().toLocaleLowerCase();return (matchResult.value?.matches||[]).filter(m=>!q||discoveryName(m).toLocaleLowerCase().includes(q)).slice(0,24)})
let ctl:AbortController|null=null;const featuredCtl=new AbortController()
watch(()=>route.fullPath,async()=>{query.value=typeof route.query.q==='string'?route.query.q:'';leafShape.value=String(route.query.leafShape||'');flowerColour.value=String(route.query.flowerColour||'');growthForm.value=String(route.query.growthForm||'');ctl?.abort();matchResult.value=null;matchError.value='';if(!hasTraits.value){matchLoading.value=false;void plants.search(query.value);return}const current=new AbortController();ctl=current;matchLoading.value=true;try{const r=await fetch('/api/v1/science/identify?'+discoveryParams(route.query),{signal:current.signal});if(!r.ok)throw Error(`外观资料暂不可用（${r.status}）`);const data=await r.json() as DiscoveryResult;if(ctl===current)matchResult.value=data}catch(e){if(!current.signal.aborted)matchError.value=(e as Error).message}finally{if(ctl===current)matchLoading.value=false}},{immediate:true})
onMounted(async()=>{const rows=await Promise.allSettled([2,9445,30610,37548,26923,43231].map(id=>fetch(`/api/v1/plants/${id}`,{signal:featuredCtl.signal}).then(async r=>{if(!r.ok)throw Error();return await r.json() as PlantRecord})));if(!featuredCtl.signal.aborted)featured.value=rows.flatMap(r=>r.status==='fulfilled'?[r.value]:[])})
onUnmounted(()=>{ctl?.abort();featuredCtl.abort();plants.cancel()})
function search(clear=false){void router.push({path:'/explore',query:{...(!clear&&query.value.trim()?{q:query.value.trim()}:{}),...(!clear&&leafShape.value?{leafShape:leafShape.value}:{}),...(!clear&&flowerColour.value?{flowerColour:flowerColour.value}:{}),...(!clear&&growthForm.value?{growthForm:growthForm.value}:{})}})}
function show(plant:PlantRecord){selected.value=plant;preview.value?.showModal()}
</script>
<template><main class="museum-gallery"><header class="gallery-intro"><div><p class="museum-eyebrow">THE BOTANICAL GALLERY</p><h1>来，<em>认识一点自然。</em></h1><p>从一个熟悉的名字开始，或顺着叶与花的线索随意逛逛。</p></div><span class="gallery-drawing" aria-hidden="true"><UiIcon name="leaf" :size="90"/></span></header>
<form class="gallery-search" @submit.prevent="search()"><UiIcon name="search"/><PlantSearchInput v-model="query" label="搜索植物名称" placeholder="你想认识哪株植物？中文名、学名、科属都可以" @select="router.push(`/plants/${$event.id}`)"/><button class="museum-button" :aria-busy="plants.loading||matchLoading">{{plants.loading||matchLoading?'寻找中…':'寻找植物'}}<UiIcon name="arrow" :size="18"/></button></form>
<details class="gallery-advanced" :open="hasTraits"><summary><UiIcon name="filter" :size="16"/> 想找得更细一点？展开外观与名称筛选</summary><form @submit.prevent="search()"><label>叶片轮廓<select v-model="leafShape"><option value="">不限</option><option value="LANCEOLATE">披针形</option><option value="OVATE">卵形</option><option value="ELLIPTIC">椭圆形</option><option value="LINEAR">线形</option><option value="OBLONG">长圆形</option></select></label><label>花的颜色<select v-model="flowerColour"><option value="">不限</option><option v-for="[value,name] in [['WHITE','白色'],['YELLOW','黄色'],['RED','红色'],['PINK','粉色'],['PURPLE','紫色'],['BLUE','蓝色'],['GREEN','绿色']]" :key="value" :value="value">{{name}}</option></select></label><label>生长姿态<select v-model="growthForm"><option value="">不限</option><option value="TREE">乔木</option><option value="SHRUB">灌木</option><option value="HERB">草本</option><option value="VINE">藤本</option></select></label><button class="museum-button">沿这些特征寻找</button><button type="button" class="plain-button" @click="search(true)">清除条件</button><p>外观来自公开来源记载，不是识别或鉴定结论。名称条件在当前返回的有限特征批次内筛选；未知特征不作为冲突。</p></form></details>
<DiscoveryPaths v-if="!appliedQuery&&!hasTraits"/>
<section class="gallery-collection" aria-label="植物查询结果" :aria-busy="hasTraits?matchLoading:plants.loading"><header><div><p class="museum-eyebrow">{{hasTraits?'FOLLOW A DETAIL':'TAKE YOUR TIME'}}</p><h2>{{hasTraits?'顺着这个细节，看见更多。':appliedQuery?'与你寻找的名字相遇。':'把目光，留给植物。'}}</h2></div><div v-if="!hasTraits" class="atlas-view-toggle" aria-label="结果布局"><button :aria-pressed="layout==='grid'" @click="layout='grid'">画廊</button><button :aria-pressed="layout==='list'" @click="layout='list'">名称列表</button></div></header>
<p v-if="appliedQuery||hasTraits" class="gallery-result-note"><button class="plain-button" @click="search(true)">← 回到整个画廊</button><span v-if="appliedQuery">“{{appliedQuery}}”</span><span v-if="leafShape">叶形：{{leafShape}}</span><span v-if="flowerColour">花色：{{flowerColour}}</span><span v-if="growthForm">生长型：{{growthForm}}</span></p>
<template v-if="hasTraits"><p v-if="matchLoading" role="status" class="museum-loading">正在翻阅外观来源记录…</p><div v-else-if="matchError" class="state-notice state-notice--error" role="alert">{{matchError}} <button @click="search(true)">回到名称探索</button></div><template v-else><p class="gallery-result-note">以下为来源特征记录，保留资料中的学名；尚未建立物种目录关联时，不冒认植物身份。</p><div v-if="matches.length" class="discovery-matches"><article v-for="m in matches" :key="m.factId"><BotanicalImage :name="discoveryName(m)" :caption="false"/><div><small>{{m.knowledgeConfidence==='MACHINE_EXTRACTED'?'自动整理 · 来源特征':'资料记载 · 来源特征'}}</small><h3>{{discoveryName(m)}}</h3><p v-if="discoverySnippet(m)">{{discoverySnippet(m)}}</p><RouterLink :to="{path:'/knowledge-graph',query:{nodeId:`candidate:${m.factId}`}}">这条知识来自哪里 ↗</RouterLink><RouterLink :to="{path:'/explore',query:{q:discoveryName(m)}}">查找同名植物目录 →</RouterLink></div></article></div><p v-else class="museum-loading">这批资料还不足以给出匹配。未知不等于不符合；<RouterLink to="/explore">试试从名称开始。</RouterLink></p><p v-if="matchResult?.truncated" class="museum-fineprint">当前查询仅检查服务端限定的首批来源，结果可能不完整；这里展示最多24条，不表示全库物种数量。</p></template></template>
<template v-else><div v-if="plants.error" class="state-notice state-notice--error" role="alert"><h3>这一页暂时没有读到</h3><p>{{plants.error}}</p><button @click="plants.search(query)">再试一次</button></div><p v-else-if="plants.loading&&!visiblePlants.length" class="museum-loading" role="status">正在打开植物画廊…</p><div v-else-if="!visiblePlants.length" class="museum-loading"><h3>这次，还没有遇见。</h3><p>换一个短些的名字试试。没有找到记录，不代表植物不存在。</p><button class="museum-button" @click="search(true)">继续随意逛逛</button></div><div v-else class="botanical-grid museum-gallery-grid" :class="{'is-list':layout==='list'}"><BotanicalCard v-for="plant in visiblePlants" :key="plant.id" :plant="plant" :compact="layout==='list'" @preview="show"/></div><div v-if="plants.nextAfterId" class="atlas-pagination"><button class="museum-button" :disabled="plants.loading" @click="plants.loadMore()">{{plants.loading?'翻页中…':'再往前逛一页'}} <UiIcon name="arrow" :size="18"/></button></div><p v-if="!plants.loading&&!plants.error" class="museum-fineprint">名称目录 {{plants.total.toLocaleString('zh-CN')}} 条 · 按需读取。影像只用于图鉴；没有对应授权图片的植物保留无图页。</p></template>
</section><dialog ref="preview" class="plant-preview-dialog" aria-label="植物快速预览"><template v-if="selected"><button class="preview-close vx-icon-button" aria-label="关闭快速预览" @click="preview?.close()"><UiIcon name="close"/></button><BotanicalImage :name="selected.scientificName" :plant-id="selected.id"/><div class="preview-copy"><p class="museum-eyebrow">A CLOSER LOOK</p><h2>{{selected.nameZh||selected.scientificName}}</h2><em>{{selected.scientificName}}</em><p>{{selected.morphology||'从名称与真实来源，继续认识这株植物。'}}</p><p>{{selected.sourceDocument||'公开来源目录'}}</p><RouterLink class="museum-button" :to="`/plants/${selected.id}`" @click="preview?.close()">走近这株植物 <UiIcon name="arrow"/></RouterLink></div></template></dialog>
</main></template>
